Translate("ptBR", "duskwood", {
	title = "Floresta do Crepúsculo",
	sections = {
		{
			title = "Resumo",
			text = [=[A Floresta do Crepúsculo é uma floresta de noite sem fim no sul do {link:kingdom-of-stormwind}Reino de Ventobravo{/link}. Suas velhas árvores se fecham no alto, de modo que nenhum dia verdadeiro chega ao chão. Os mortos andam por seus cemitérios, homens-lobo rondam seus bosques e aranhas fazem ninho ao longo de seus rios. No leste fica a cidade de {link:darkshire}Vila Sombria{/link}, onde o último povo que não fugiu mantém suas tochas acesas e suas portas trancadas.]=],
		},
		{
			title = "Origens",
			text = [=[A floresta nem sempre foi assim. Os que a conheceram antes das guerras se lembram de bosques verdes, fazendas movimentadas e uma aldeia que desde então tomou o nome de {link:darkshire}Vila Sombria{/link}. Na {link:first-war}Primeira Guerra{/link}, a {link:horde}Horda{/link} queimou estes bosques como queimou {link:elwynn-forest}Elwynn{/link}. As fazendas foram erguidas de novo depois. Então, nos anos em que os homens do reino marcharam para o norte, para a {link:third-war}Terceira Guerra{/link}, veio algo mais imundo. Uma magia que ninguém em Vila Sombria sabe nomear se infiltrou na terra. As folhas escureceram, as covas se abriram, e a floresta vive no crepúsculo desde então.]=],
		},
		{
			title = "O Presente",
			text = [=[A Floresta do Crepúsculo está sozinha. Quando a escuridão chegou, {link:stormwind-city}Ventobravo{/link} chamou seus guardas de volta para casa e não os mandou de novo. A cidade ergueu sua própria milícia, a {link:the-night-watch}Vigília Noturna{/link}, sob a {link:commander-althea-ebonlocke}Comandante Althea Ebonlocke{/link}, e defende desde então o coração da floresta com espadas de menos. A Vigília não é o único perigo para a paz de {link:darkshire}Vila Sombria{/link}. Os senhores de Ventobravo anulam as sentenças de seu conselho, e um de seus conselheiros fala abertamente em romper com a coroa. Além das muralhas, os {link:nightbane-worgen}worgens Nightbane{/link} tomaram o sul, os mortos ocupam {link:raven-hill}Monte Corvo{/link}, ogros ocupam as grutas do sul, e a {link:defias-brotherhood}Irmandade Défias{/link} usa as fazendas do oeste como estrada para suas tramas. Cavaleiros sombrios saem da {link:deadwind-pass}Trilha do Vento Morto{/link}, a leste, e ninguém sabe o que querem.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}O povo de {link:darkshire}Vila Sombria{/link}.{/b} Mercadores, ferreiros, uma vidente, um historiador e um conselho que ainda se reúne na prefeitura. A maioria perdeu alguém para a floresta.
• {b}{link:the-night-watch}A Vigília Noturna{/link}.{/b} Vigias guardam os portões da cidade, a praça e um punhado de postos solitários nas estradas.
• {b}A família Carevin.{/b} Uma casa de caçadores que trava sua própria guerra contra demônios e mortos-vivos.
• {b}Os mortos.{/b} Esqueletos, carniçais e espíritos inquietos enchem o {link:raven-hill-cemetery}Cemitério de Monte Corvo{/link} e os {link:tranquil-gardens-cemetery}Jardins da Paz{/link}.
• {b}Os {link:nightbane-worgen}Nightbane{/link}.{/b} Worgens que surgiram como que do nada, e que agora ocupam o sul da floresta.
• {b}Os ogros.{/b} O clã Splinter Fist mantém a {link:vul-gol-ogre-mound}Gruta de Vul'Gol{/link}.
• {b}Os Renegados.{/b} Uma pequena expedição dos {link:forsaken}Renegados{/link} se esconde no {link:beggar-s-haunt}Refúgio dos Mendigos{/link}, no extremo leste.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Velha Floresta.{/b} Antes das guerras, a floresta era verde, e suas fazendas e aldeias prosperavam.
• {b}A {link:first-war}Primeira Guerra{/link}.{/b} A {link:horde}Horda{/link} queimou os bosques a caminho de {link:stormwind-city}Ventobravo{/link}.
• {b}O Escurecimento.{/b} Nos anos da {link:third-war}Terceira Guerra{/link}, uma magia imunda tomou conta da floresta. {link:raven-hill}Monte Corvo{/link} caiu, e seu povo com ele. Ventobravo retirou seus guardas, e {link:darkshire}Vila Sombria{/link} ergueu a {link:the-night-watch}Vigília Noturna{/link} no lugar deles.
• {b}O Presente.{/b} Vila Sombria resiste, mas por pouco, e seu povo começou a se perguntar se o reino ainda os conta entre os seus.]=],
		},
		{
			title = "Lendas do Bosque",
			text = [=[• As crianças de {link:darkshire}Vila Sombria{/link} crescem ouvindo a história de um alquimista bondoso chamado o {link:abercrombie}Embalsamador{/link}, que enlouqueceu de dor pela esposa morta.
• O nome de {link:stalvan-mistmantle}Stalvan Mistmantle{/link} só é dito na cidade num sussurro.
• Os que se perdem nos bosques escuros às vezes dizem que uma sombra os levou de volta à estrada.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica destes dias registra o que primeiro escureceu a Floresta do Crepúsculo, nem o ano em que isso aconteceu.]=],
		},
	},
})

Translate("ptBR", "darkshire", {
	title = "Vila Sombria",
	sections = {
		{
			title = "Resumo",
			text = [=[Vila Sombria é a última cidade de verdade da {link:duskwood}Floresta do Crepúsculo{/link}, um aglomerado de casas de madeira em volta de uma praça no leste da floresta. {link:the-night-watch}A Vigília Noturna{/link} guarda seus portões. O prefeito, {link:lord-ello-ebonlocke}Lorde Ello Ebonlocke{/link}, despacha na prefeitura com seu conselho e seu escrivão. Os viajantes bebem na Scarlet Raven Tavern, onde o cozinheiro serve bolinhos de origem duvidosa. Uma vidente lê as cartas numa casa da praça, e um historiador mantém uma biblioteca que fica mais magra a cada ano. O povo daqui mantém suas lamparinas acesas a noite toda.]=],
		},
	},
})

Translate("ptBR", "raven-hill", {
	title = "Monte Corvo",
	sections = {
		{
			title = "Resumo",
			text = [=[Monte Corvo foi outrora uma aldeia orgulhosa no oeste da {link:duskwood}Floresta do Crepúsculo{/link}. Agora é uma cidade-fantasma. Suas casas estão vazias, e seu povo jaz no grande cemitério ao norte. Poucos registros da aldeia sobreviveram à sua queda, e até o historiador de {link:darkshire}Vila Sombria{/link} pouco sabe dizer dela. Ultimamente, os moradores ouviram falar de sombras que se movem entre suas casas e de uma luz numa janela. A assombração era apenas um homem assustado escondido. Os fantasmas da {link:the-valor-family}família Valor{/link}, que um dia defendeu a aldeia, são outra história.]=],
		},
	},
})

Translate("ptBR", "raven-hill-cemetery", {
	title = "Cemitério de Monte Corvo",
	sections = {
		{
			title = "Resumo",
			text = [=[O Cemitério de Monte Corvo se estende pelo noroeste da {link:duskwood}Floresta do Crepúsculo{/link}, tão vasto que agora domina a terra ao seu redor. Os esqueletos de seus mortos marcham em fileiras entre as lápides, e carniçais infestam seus mausoléus. {link:the-night-watch}A Vigília Noturna{/link} mandou voluntários para cá vezes sem conta, e ainda assim os mortos voltam. Aqui o cavaleiro {link:mor-ladim}Morgan Ladimore{/link} encontrou os túmulos de sua família, e aqui seu próprio túmulo foi depois encontrado vazio. Num barraco em sua borda norte vive um velho eremita. Perto de sua porta fica o túmulo de uma mulher chamada {link:eliza}Eliza{/link}.]=],
		},
	},
})

Translate("ptBR", "forlorn-rowe", {
	title = "Morro dos Esquecidos",
	sections = {
		{
			title = "Resumo",
			text = [=[O Morro dos Esquecidos é uma casa numa colina acima do {link:raven-hill-cemetery}Cemitério de Monte Corvo{/link}. É o covil do necromante {link:morbent-fel}Morbent Fel{/link}, e é aqui que os {link:dark-riders}cavaleiros sombrios{/link} da {link:deadwind-pass}Trilha do Vento Morto{/link} vêm falar com ele. Os esqueletos que guardam a colina são seus servos. Por um tempo, ele comprou corpos do ladrão de túmulos {link:dextren-ward}Dextren Ward{/link}, até que Ward foi preso e mandado ao {link:the-stockade}Cárcere de Ventobravo{/link}. {link:sven-yorgen}Sven Yorgen{/link} vigia esta casa de seu acampamento no oeste, e espera o dia em que ela fique em silêncio.]=],
		},
	},
})

Translate("ptBR", "manor-mistmantle", {
	title = "Casarão dos Brumanto",
	sections = {
		{
			title = "Resumo",
			text = [=[O Casarão dos Brumanto fica pouco ao norte de {link:darkshire}Vila Sombria{/link}, uma casa solitária sob as árvores negras. Seu senhor é {link:stalvan-mistmantle}Stalvan Mistmantle{/link}, um homem que já foi professor de crianças e cujo nome hoje é sinônimo de assassinato. Ele veio da {link:silverpine-forest}Floresta de Pinhaprata{/link}, muito ao norte, e certa vez assinava suas cartas com o nome de sua terra natal. {link:the-night-watch}A Vigília Noturna{/link} por muito tempo suspeitou dele por velhos assassinatos, mas nada pôde provar. Os moradores evitam a casa, e os que passam por ela à noite não se demoram.]=],
		},
	},
})

Translate("ptBR", "roland-s-doom", {
	title = "O Descanso de Rolando",
	sections = {
		{
			title = "Resumo",
			text = [=[O Descanso de Rolando é uma mina no sul da {link:duskwood}Floresta do Crepúsculo{/link}. Seus túneis já eram um lugar difícil de trabalhar, mas não mortal, até que um mineiro puxou o cabo de uma estranha foice de um monte de entulho. Naquela noite, os worgens saíram da própria rocha. Metade dos mineiros morreu nos primeiros momentos. Os {link:nightbane-worgen}Nightbane{/link} ainda ocupam a mina, e suas fogueiras podem ser vistas de longe. Aqui foram encontrados os primeiros worgens da Floresta do Crepúsculo, e aqui termina a trilha da {red:scythe-of-elune}Foice de Eluna{/red}.]=],
		},
	},
})

Translate("ptBR", "addle-s-stead", {
	title = "Quinta dos Aguiar",
	sections = {
		{
			title = "Resumo",
			text = [=[A Quinta dos Aguiar é uma fazenda abandonada no sudoeste da {link:duskwood}Floresta do Crepúsculo{/link}, ao sul da estrada que vem do {link:westfall}Cerro Oeste{/link}. Seus fazendeiros se foram. A {link:defias-brotherhood}Irmandade Défias{/link} fez dela um ponto de encontro, e suas lâminas noturnas e encantadores montam guarda entre os campos arruinados. Algum tempo atrás, a {link:the-night-watch}Vigília Noturna{/link} viu ali uma reunião de agentes Défias, grande o bastante para sugerir que algo importante passara por lá. Dizem que o fantasma de uma guarda de {link:raven-hill}Monte Corvo{/link} ainda anda por seus campos.]=],
		},
	},
})

Translate("ptBR", "the-rotting-orchard", {
	title = "O Horto Pútrido",
	sections = {
		{
			title = "Resumo",
			text = [=[O Horto Pútrido fica a sudoeste de {link:darkshire}Vila Sombria{/link}. Suas árvores ainda estão de pé em fileiras, mas seus frutos caíram há muito e apodreceram. Os {link:nightbane-worgen}worgens Nightbane{/link} o tomaram. Seus tecelões das sombras e corredores sombrios caçam entre os troncos, e é para cá que os caçadores da família Carevin mandam os que desejam se juntar a eles. Seu caçador {link:calor}Calor{/link} descobriu que os corredores sombrios são o grosso dos Nightbane, e que para cada um morto outro logo toma seu lugar.]=],
		},
	},
})

Translate("ptBR", "the-yorgen-farmstead", {
	title = "Fazenda dos Figueira",
	aliases = { "Fazenda de Sven" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Fazenda dos Figueira fica no sul da {link:duskwood}Floresta do Crepúsculo{/link}. Era o lar de {link:sven-yorgen}Sven Yorgen{/link} e sua família, até que os {link:dark-riders}cavaleiros sombrios{/link} da {link:deadwind-pass}Trilha do Vento Morto{/link} chegaram enquanto Sven estava fora e massacraram todos lá dentro. Quando Sven voltou, viu uma figura sombria enterrando algo atrás de um velho toco perto do celeiro. O que havia naquele buraco era um diário. Ele contava de um mineiro que fugira do Descanso de Rolando e se escondera no celeiro dos Yorgen, e que viu a família morrer.]=],
		},
	},
})

Translate("ptBR", "vul-gol-ogre-mound", {
	title = "Gruta de Vul'Gol",
	aliases = { "Vul'Gol" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Gruta de Vul'Gol é um labirinto de cavernas no sul da {link:duskwood}Floresta do Crepúsculo{/link}, ocupado pelos {link:ogres}ogros{/link} do clã Splinter Fist. Seus guerreiros, tecelões de fogo e capatazes atacam as estradas, e levam o que encontram nelas, até o caixote de ervas e ferramentas de um velho eremita. O ogro Zzarc'Vul habita a gruta. Ele usa um grande monóculo que um estudioso de {link:darkshire}Vila Sombria{/link} cobiça para seus próprios fins. Acredita-se que o fantasma de um Vigia da velha {link:raven-hill}Monte Corvo{/link} ande pelas estradas perto da gruta, ainda em guerra com os ogros.]=],
		},
	},
})

Translate("ptBR", "brightwood-grove", {
	title = "Bosque Brilhante",
	sections = {
		{
			title = "Resumo",
			text = [=[O Bosque Brilhante é uma extensão de mata na {link:duskwood}Floresta do Crepúsculo{/link}. Seja qual for o brilho que lhe deu nome, ele se foi. Os {link:nightbane-worgen}worgens Nightbane{/link} caçam ali, seus tecelões das sombras movendo-se em bandos entre as árvores, e os caçadores de {link:darkshire}Vila Sombria{/link} falam do nome do bosque com um riso amargo. Como o Horto Pútrido, é um campo de provas da família Carevin. Os que querem se juntar à guerra dos Carevin precisam primeiro voltar vivos de suas sombras.]=],
		},
	},
})

Translate("ptBR", "twilight-grove", {
	title = "Bosque do Crepúsculo",
	sections = {
		{
			title = "Resumo",
			text = [=[O Bosque do Crepúsculo fica no coração da {link:duskwood}Floresta do Crepúsculo{/link}, ao norte da estrada que atravessa a floresta. Uma grande árvore se ergue ali. É um dos poucos lugares dos {link:eastern-kingdoms}Reinos do Leste{/link} onde o mundo desperto toca o {link:emerald-dream}Sonho Esmeralda{/link}, o reino que os dragões verdes guardam. Tais portais são raros no mundo, e os outros ficam longe, nas {link:the-hinterlands}Terras Agrestes{/link} e em {link:kalimdor}Kalimdor{/link}. Ninguém do povo de {link:darkshire}Vila Sombria{/link} fala do bosque, e ninguém afirma saber por que tal lugar ficaria numa floresta dos mortos.]=],
		},
	},
})

Translate("ptBR", "tranquil-gardens-cemetery", {
	title = "Cemitério Jardins da Paz",
	aliases = { "Jardins da Paz" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Cemitério Jardins da Paz fica ao sul de {link:darkshire}Vila Sombria{/link}, no sudeste da {link:duskwood}Floresta do Crepúsculo{/link}. Seu nome é agora uma piada cruel. Guerreiros e magos esqueléticos andam entre seus túmulos, e um carniçal insano vaga por seus caminhos com um espelho roubado. É o cemitério da floresta mais próximo da cidade. Seus esqueletos carregam flores podres nos crânios, flores que o taberneiro de Vila Sombria transforma num licor forte o bastante para erguer os mortos. Quando os mortos se levantam ali, a {link:the-night-watch}Vigília Noturna{/link} é a primeira a saber.]=],
		},
	},
})

Translate("ptBR", "the-hushed-bank", {
	title = "Margem Silenciada",
	sections = {
		{
			title = "Resumo",
			text = [=[A Margem Silenciada corre ao longo do rio, na borda oeste extrema da {link:duskwood}Floresta do Crepúsculo{/link}. Aqui {link:sven-yorgen}Sven Yorgen{/link} mantém seu acampamento com seu companheiro Lars e alguns seguidores leais. São tão poucos que nenhum pode ser dispensado para buscar mantimentos, e por isso {link:carevin-family}a família Carevin{/link} de {link:darkshire}Vila Sombria{/link} lhes manda o que pode. Vivem do que conseguem caçar, e lobos atrozes famintos descem dos bosques para disputar com eles cada pedaço de carne. Desta margem solitária, Sven vigia o leste, onde o necromante {link:morbent-fel}Morbent Fel{/link} espera em sua colina.]=],
		},
	},
})

Translate("ptBR", "the-darkened-bank", {
	title = "Margem Escurecida",
	sections = {
		{
			title = "Resumo",
			text = [=[A Margem Escurecida é a longa borda norte da {link:duskwood}Floresta do Crepúsculo{/link}, onde o rio corre entre a floresta e o sopé das colinas de {link:elwynn-forest}Elwynn{/link}. Aranhas Venom Web fazem ninho ao longo de sua margem, e o chef da Scarlet Raven Tavern aprecia suas patas para seus bolinhos. {link:the-night-watch}Vigias{/link} patrulham a estrada do norte ali perto, e um deles guarda o trecho logo fora da cidade. {link:nessa-shadowsong}Nessa{/link} estrada, um comerciante goblin mantém uma banca ao lado de um Vigia solitário, vendendo artigos raros a quem ousar a viagem.]=],
		},
	},
})

Translate("ptBR", "beggar-s-haunt", {
	title = "Refúgio dos Mendigos",
	sections = {
		{
			title = "Resumo",
			text = [=[{link:the-harborage}O Refúgio{/link} dos Mendigos fica no extremo leste da {link:duskwood}Floresta do Crepúsculo{/link}, perto da fronteira da {link:deadwind-pass}Trilha do Vento Morto{/link}. Os {link:forsaken}Renegados{/link} fizeram dele um acampamento escondido. Sua expedição foi mandada para o sul por ordem de {link:varimathras}Varimathras{/link} para explorar as terras do antigo reino de {link:azeroth}Azeroth{/link}. Um boticário da {link:royal-apothecary-society}Real Sociedade de Boticários{/link} trabalha ali com um Deathstalker. Quando um espião humano foi pego vigiando seu acampamento, foram os orcs de {link:stonard}Pedregal{/link} que o levaram, e os Renegados estavam ansiosos para saber o que ele sabia.]=],
		},
	},
})

Translate("ptBR", "commander-althea-ebonlocke", {
	title = "Comandante Althea Ebonlocke",
	subtitle = "Líder da Vigília Noturna",
	found = "Vila Sombria, diante da prefeitura",
	hint = [=[Fale com a comandante que lidera a Vigília Noturna de Vila Sombria.]=],
	allegiance = "A Vigília Noturna · Vila Sombria",
	aliases = { "Althea Ebonlocke", "Althea" },
	sections = {
		{
			title = "Resumo",
			text = [=[Althea Ebonlocke comanda a {link:the-night-watch}Vigília Noturna{/link}, a milícia que guarda {link:darkshire}Vila Sombria{/link} agora que os soldados de {link:stormwind-city}Ventobravo{/link} se foram. É severa e tem pouca paciência, e não tem tempo para pistas que não levam a lugar nenhum. Seus Vigias são poucos demais para a floresta que precisam defender. Ela pede ajuda a qualquer estranho disposto a dá-la, e não desperdiça o tempo deles com cerimônias.]=],
		},
		{
			title = "Importância",
			text = [=[O povo de {link:darkshire}Vila Sombria{/link} deve sua sobrevivência a ela mais que a qualquer outro. O historiador da cidade a conta entre os heróis sem os quais Vila Sombria teria caído.]=],
		},
		{
			title = "Feitos",
			text = [=[• Defende {link:darkshire}Vila Sombria{/link} e suas estradas com um punhado de {link:the-night-watch}Vigias{/link}.
• Manda voluntários contra os mortos dos {link:tranquil-gardens-cemetery}Jardins da Paz{/link} e de {link:raven-hill}Monte Corvo{/link}.
• Vigiou {link:stalvan-mistmantle}Stalvan Mistmantle{/link} por anos, certa de sua culpa, mas incapaz de prová-la.
• Perdeu alguns de seus Vigias mais fortes para o cavaleiro morto errante {link:mor-ladim}Mor'Ladim{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Os Mortos da Floresta do Crepúsculo",
			hint = "Atenda ao chamado da comandante contra os mortos-vivos.",
			text = [=[Começou com os esqueletos dos {link:tranquil-gardens-cemetery}Jardins da Paz{/link}, logo ao sul da cidade. Depois vieram os relatos de {link:raven-hill}Monte Corvo{/link}, onde os mortos eram ainda mais numerosos, e por fim do mausoléu leste do grande cemitério, onde os espalhadores de peste fazem ninho. A cada vez, Althea não tinha {link:the-night-watch}Vigias{/link} para dispensar. A cada vez, um estranho foi no lugar deles.]=],
		},
		{
			title = "A Prova",
			hint = [=[Traga à comandante a evidência que ela espera há tanto tempo.]=],
			text = [=[Por anos ela vigiara {link:stalvan-mistmantle}Stalvan{/link} sem poder tocá-lo. Quando as páginas do diário foram postas diante dela, e o escrivão da cidade jurou que a letra batia com o registro, ela já não precisou de paciência. Deu a ordem para que Stalvan fosse executado.]=],
		},
		{
			title = "O Cavaleiro sem Descanso",
			hint = "Saiba pela comandante o destino de Morgan Ladimore.",
			text = [=[O morto-vivo que se chama {link:mor-ladim}Mor'Ladim{/link} matara gente por toda a floresta e abatera suas patrulhas. Quando o crânio dele lhe foi trazido, Althea agradeceu. Depois admitiu o que não dissera antes: que a filha do cavaleiro morto era uma de seus próprios {link:the-night-watch}Vigias{/link}.]=],
		},
	},
	mentions = {
