		{
			title = "Importância",
			text = [=[As crianças de {link:darkshire}Vila Sombria{/link} conhecem o Embalsamador de uma história para dormir. Ele era um alquimista bondoso e, quando sua esposa {link:eliza}Eliza{/link} morreu, a dor o enlouqueceu. Pôs seu próprio coração no peito dela para trazê-la de volta. Ela se ergueu de novo com fome de carne humana, e ele teve de mantê-la enterrada. A história é verdadeira, e o Embalsamador vive ao lado do túmulo dela.]=],
		},
		{
			title = "Feitos",
			text = [=[• Reuniu linha de cabelo de fantasma, suco de zumbi e costelas de carniçal pelas mãos de estranhos.
• Construiu uma criatura de carne, osso e metal para mandar contra {link:darkshire}Vila Sombria{/link}.
• Escreveu ao prefeito numa escrita que ninguém na cidade conseguia ler.]=],
		},
		{
			title = "Não Registrado",
			text = [=[O verdadeiro nome do eremita, sua idade e os anos de sua loucura não estão escritos em lugar algum.]=],
		},
	},
	chapters = {
		{
			title = "Os Favores de um Velho",
			hint = [=[Ajude o eremita com as coisas que ele não pode buscar sozinho.]=],
			text = [=[A linha, disse ele, era para suas portas e janelas, para afastar espíritos. O suco era para aquecê-lo nas noites frias. As costelas eram para um espantalho contra carniçais. Cada coisa era inofensiva por si só. Todas foram para a mesma obra.]=],
		},
		{
			title = "A Criatura à Porta",
			hint = "Descubra o que a carta do eremita diz de verdade.",
			text = [=[Traduzida, a carta era uma bravata. Abercrombie se dizia um criador. Sua obra mais recente esperava fora de seu barraco, rangendo os dentes, pronta para marchar sobre {link:darkshire}Vila Sombria{/link} a uma palavra sua. O estranho que o ajudara a construíra sem saber.]=],
