Translate("ptBR", "mor-ladim", {
	title = "Mor'Ladim",
	subtitle = "O Cavaleiro sem Descanso",
	found = "Vagando pelo Cemitério de Monte Corvo",
	hint = [=[Enfrente o cavaleiro morto que vaga pelo Cemitério de Monte Corvo.]=],
	allegiance = "Nenhuma",
	aliases = { "Morgan Ladimore" },
	sections = {
		{
			title = "Resumo",
			text = [=[Morgan Ladimore era um cavaleiro que lutava pelos inocentes e pelos pobres. Casou-se com uma moça chamada Lys quando tinha dezoito anos, e tiveram um filho e duas filhas. Quando a guerra chegou a {link:lordaeron}Lordaeron{/link}, ele foi para o norte lutar ao lado de {link:uther-the-lightbringer}Uther, o Arauto da Luz{/link}. Voltou para casa e encontrou sua floresta podre e sua casa em ruínas. Agora anda pelo cemitério como Mor'Ladim, uma coisa morta que mata sem motivo.]=],
		},
		{
			title = "Importância",
			text = [=[A queda de {link:morgan-stern}Morgan{/link} é a história mais triste da {link:duskwood}Floresta do Crepúsculo{/link}. Ele era um homem bom quebrado pela dor. Seu nome é um aviso do que a escuridão da floresta pode fazer até ao coração mais forte.]=],
		},
		{
			title = "Feitos",
			text = [=[• Serviu {link:uther-the-lightbringer}Uther{/link} durante a guerra no norte e viu a ordem dos paladinos dissolvida, Uther morto e a peste espalhada.
• Procurou sua família em cada fazenda e casa da {link:duskwood}Floresta do Crepúsculo{/link}.
• No {link:raven-hill-cemetery}Cemitério de Monte Corvo{/link}, encontrou uma lápide com o nome de sua esposa.
• Em sua dor, matou três zeladores do cemitério e depois tirou a própria vida.]=],
		},
	},
	chapters = {
		{
			title = "O Túmulo Desgastado",
			hint = [=[Procure um túmulo na borda distante do Cemitério de Monte Corvo.]=],
			text = [=[Ele foi enterrado às pressas, sem ritos, além da borda do cemitério. Dias depois, a terra fora revolvida, e o túmulo estava vazio. O historiador de {link:darkshire}Vila Sombria{/link}, que conhecera {link:morgan-stern}Morgan{/link} antes da guerra, guarda um livro que conta sua história.]=],
		},
		{
			title = "O Anel de uma Filha",
			hint = "Leve consolo ao túmulo de Morgan Ladimore.",
			text = [=[{link:morgan-stern}Morgan{/link} morreu acreditando que toda a sua família estava morta. Uma filha, Sarah, sobrevivera. Quando o anel dela foi posto sobre seu túmulo, uma voz se ergueu no vento. O cavaleiro disse o nome da filha com espanto, e o peso em sua alma foi erguido. Deu sua espada, Archeus, a quem lhe trouxera paz, e suas últimas palavras foram para a esposa, Lys.]=],
		},
	},
	mentions = {
		{ text = "O Túmulo Desgastado" },
		{ text = "Morgan Ladimore" },
		{ text = "Mor'Ladim" },
		{ text = "O Amor de uma Filha" },
	},
	bonds = {
