	hint = [=[Cuidado com a criatura que marcha pela estrada em direção a Vila Sombria.]=],
	allegiance = "O Embalsamador",
	sections = {
		{
			title = "Resumo",
			text = [=[Stitches é a criatura do {link:abercrombie}Embalsamador{/link}, feita de carne, osso e metal retorcido. Foi construída com as próprias coisas que um estranho levou ao barraco do eremita, e esperou do lado de fora desse barraco pela palavra de seu senhor. Quando a palavra veio, marchou pela estrada em direção a {link:darkshire}Vila Sombria{/link} para massacrar o que encontrasse.]=],
		},
		{
			title = "Importância",
			text = [=[Stitches é a prova de que a velha história infantil do {link:abercrombie}Embalsamador{/link} era verdadeira, e de que o louco não parara de fazer coisas.]=],
		},
		{
			title = "Feitos",
			text = [=[• Esperou do lado de fora do barraco do eremita pela palavra de seu criador.
• Partiu para {link:darkshire}Vila Sombria{/link} logo depois que a carta do {link:abercrombie}Embalsamador{/link} foi traduzida.]=],
		},
	},
	mentions = {
		{ text = "Tradução para Ello" },
	},
	bonds = {
		{ id = "abercrombie", name = "Abercrombie", note = "seu criador" },
	},
})

Translate("ptBR", "avette-fellwood", {
	title = "Avette Fellwood",
	subtitle = "Artesã de Arcos de Vila Sombria",
	found = "Vila Sombria, em sua banca de arcos",
	hint = [=[Procure a artesã de arcos de Vila Sombria que acolheu um menino órfão.]=],
	allegiance = "Vila Sombria",
	aliases = { "Avette" },
	sections = {
		{
			title = "Resumo",
			text = [=[Avette Fellwood é uma artesã de arcos de {link:darkshire}Vila Sombria{/link}. Adotou há pouco Jeremy Heartweaver, um menino que sobreviveu à queda de {link:lordaeron}Lordaeron{/link} e foi levado a um orfanato em {link:stormwind-city}Ventobravo{/link}. Jeremy não fala desde o ataque à sua cidade. Seu pai, Edward, ergueu-se entre os {link:forsaken}Renegados{/link} e procurava toda semana o corpo do filho nas ruínas da capital, até que um dia não voltou. Sua última carta, manchada de sangue, chegou às mãos de Avette.]=],
		},
		{
			title = "Importância",
			text = [=[Avette escolheu proteger o menino em vez de feri-lo. Não esconderá dele seu passado. {link:dar}Dar{/link}á a ele a carta do pai quando tiver idade para suportá-la.]=],
		},
	},
	mentions = {
		{ text = "Lembre-se de que Eu Te Amo" },
	},
	bonds = {
		{ id = "ruins-of-lordaeron", name = "Ruínas de Lordaeron", note = "onde a carta foi encontrada" },
	},
})

Translate("ptBR", "the-night-watch", {
	title = "A Vigília Noturna",
	aliases = { "Vigília Noturna", "Vigias" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Vigília Noturna é a milícia de {link:darkshire}Vila Sombria{/link}. Foi erguida quando uma magia imunda se infiltrou na {link:duskwood}Floresta do Crepúsculo{/link} e {link:stormwind-city}Ventobravo{/link} chamou seus guardas de volta para casa. Desde então, a Vigília é tudo o que se interpõe entre a cidade e a floresta. É liderada pela {link:commander-althea-ebonlocke}Comandante Althea Ebonlocke{/link}, e seus membros são chamados Vigias.]=],
		},
		{
			title = "Os Vigias",
			text = [=[Os Vigias guardam os portões e a praça de {link:darkshire}Vila Sombria{/link}, e alguns mantêm postos solitários nas estradas: dois na estrada do oeste, um na estrada do norte, ao lado de um comerciante goblin. São poucos demais, e sabem disso. Sua comandante não pode mandá-los para longe da cidade. Quando os mortos se levantam nos cemitérios, ela precisa pedir a estranhos que vão no lugar deles. O cavaleiro morto {link:mor-ladim}Mor'Ladim{/link} matou alguns de seus mais fortes.]=],
		},
		{
			title = "A Vigília e o Mundo",
			text = [=[{link:darkshire}Vila Sombria{/link} passou a depender da Vigília como seu único exército. Quando o {link:magistrate-solomon}Magistrado Solomon{/link}, de {link:lakeshire}Vila Plácida{/link}, a implorou ao {link:lord-ello-ebonlocke}Lorde Ebonlocke{/link}, o prefeito recusou: se a Vigília marchasse, a cidade cairia antes que ela chegasse à borda da floresta. Nem todos a admiram. O caçador {link:calor}Calor{/link} deixou a Vigília pela família Carevin, chamando-a de acomodada. Entre os Vigias estão {link:sarah-ladimore}Sarah Ladimore{/link}, filha de um cavaleiro caído, e, nas histórias de {link:raven-hill}Monte Corvo{/link}, o arqueiro Merrick Valor.]=],
		},
	},
})

Translate("ptBR", "nightbane-worgen", {
	title = "Worgens Nightbane",
	aliases = { "Nightbane", "worgens Nightbane" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Nightbane são os {red:worgen}worgens{/red} da {link:duskwood}Floresta do Crepúsculo{/link}: grandes homens-lobo que caçam em bandos na metade sul da floresta. Tecelões das sombras e corredores sombrios vagam pelo {link:brightwood-grove}Bosque Brilhante{/link} e pelo Horto Pútrido. Os mais fortes deles, os presas vis e os maculados, mantêm suas fogueiras perto das cavernas do sul e na mina do Descanso de Rolando.]=],
		},
		{
			title = "Sua Chegada",
			text = [=[Os worgens nem sempre estiveram aqui. Os caçadores de {link:darkshire}Vila Sombria{/link} dizem que eles surgiram como que do nada, e os primeiros foram encontrados no Descanso de Rolando. Um mineiro daquela mina, o homem chamado {link:jitters}Jitters{/link}, conta como aconteceu. Ele encontrou o cabo de uma foice num monte de entulho e o puxou. Naquela noite, os worgens saíram de cada buraco e saliência dos túneis, e a maioria dos mineiros morreu. Ele perdeu a foice na fuga. Não sabe se foi ele quem trouxe os homens-lobo à {link:duskwood}Floresta do Crepúsculo{/link}, mas teme que sim.

A foice era a {red:scythe-of-elune}Foice de Eluna{/red}. Uma sacerdotisa elfa noturna, Velinde Starsong, a trouxera para estes bosques, e seu destino foi descoberto nas minas. As {link:sentinels}Sentinelas{/link} de {link:darnassus}Darnassus{/link} ficaram inquietas por um presente de sua deusa ter saído das mãos de suas servas.]=],
		},
		{
			title = "A Guerra Contra Eles",
			text = [=[A família Carevin e seu caçador {link:calor}Calor{/link} travam uma guerra sem fim contra os Nightbane. Cada bando que destroem logo é substituído. Ninguém em {link:darkshire}Vila Sombria{/link} sabe ainda que poder os atrai.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica destes dias explica como a Foice chamou os worgens, nem se os Nightbane são parentes dos worgens da {link:silverpine-forest}Floresta de Pinhaprata{/link}.]=],
		},
	},
})

Translate("ptBR", "the-valor-family", {
	title = "A Família Valor",
	aliases = { "família Valor" },
	sections = {
		{
			title = "Resumo",
			text = [=[A família Valor era a defensora de {link:raven-hill}Monte Corvo{/link} antes de sua queda. Um tomo encontrado na aldeia arruinada, {i}Memórias de Valor{/i}, registra seus membros um a um. Seu autor lamenta por eles e se culpa por sua ausência.]=],
		},
		{
			title = "A Família",
			text = [=[• {b}Lorde Grant Valor.{/b} O chefe da família e o líder de {link:raven-hill}Monte Corvo{/link}. Quando a escuridão chegou aos bosques, foi o primeiro a reunir os aldeões. Odiava os mortos-vivos acima de todos os inimigos e patrulhava ele mesmo os cemitérios. Um ferimento grave causado por eles nunca sarou de verdade.
• {b}Lady Cassandra Valor.{/b} Sua esposa. Pouco se sabe dela além de seu amor pela família.
• {b}Silvia Valor.{/b} Uma guarda de Monte Corvo, famosa por passar bandidos e trapaceiros ao fio da espada. Dizem que nunca abandonou as fazendas da {link:duskwood}Floresta do Crepúsculo{/link}.
• {b}Ira Valor.{/b} Quando o pai adoeceu, ela foi à floresta colher alimento, e passou a preferir os bosques escuros à aldeia. Viajantes perdidos falam de uma sombra que os leva de volta à estrada.
• {b}Merrick Valor.{/b} O filho mais novo. Entrou para a {link:the-night-watch}Vigília Noturna{/link} e guardava as estradas com seu arco.]=],
		},
		{
			title = "Seus Fantasmas",
			text = [=[Os Valor desapareceram todos de uma vez. Agora seus espíritos andam pela floresta, ainda no trabalho que faziam em vida: Grant entre os esqueletos do cemitério, Silvia perto das fazendas, Ira nos bosques, Merrick nas estradas. {link:sirra-von-indi}Sirra Von'Indi{/link}, o historiador de {link:darkshire}Vila Sombria{/link}, acredita que alguma dor compartilhada os prende a este mundo.]=],
		},
		{
			title = "Não Registrado",
			text = [=[O que aconteceu aos Valor, e o que prende seus espíritos, ainda não se sabe.]=],
		},
	},
})

Translate("ptBR", "carevin-family", {
	title = "Família Carevin",
	aliases = { "os Carevin", "a família Carevin" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Carevin são uma casa de {link:darkshire}Vila Sombria{/link} que assumiu uma guerra particular. Caçam demônios, mortos-vivos e todos que os ajudam, e não confiam em ninguém que não queira ajudar sua causa. Seu chefe é {link:jonathan-carevin}Jonathan Carevin{/link}. Seu caçador {link:calor}Calor{/link}, que já foi da {link:the-night-watch}Vigília Noturna{/link}, lidera a luta contra os {link:nightbane-worgen}worgens Nightbane{/link}.]=],
		},
		{
			title = "A Casa",
			text = [=[Elaine Carevin cuida das necessidades dos excluídos da cidade. Manda mantimentos a {link:sven-yorgen}Sven Yorgen{/link}, no oeste, a quem chama de homem que faz o trabalho da Luz, e se preocupa com o velho eremita que já não vem ao mercado. Scott Carevin vende cogumelos na praça, e um menino pequeno, Benjamin, brinca perto da casa.]=],
		},
		{
			title = "Os Carevin e a Vigília",
			text = [=[Os Carevin não se opõem abertamente à {link:the-night-watch}Vigília Noturna{/link}. Ainda assim, {link:calor}Calor{/link} não esconde seu desprezo por ela. Sonha com o dia em que os seguidores dos Carevin serão mais numerosos que os Vigias.]=],
		},
	},
})
